CREATE OR REPLACE FUNCTION public.contract_financial_self_healing_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_reconcile_before jsonb;
  v_generation jsonb;
  v_reconcile_after jsonb;
BEGIN
  v_reconcile_before := public.reconcile_all_contract_schedules();
  v_generation := public.generate_due_contract_invoices_v1(
    jsonb_build_object('dry_run', false)
  );
  v_reconcile_after := public.reconcile_all_contract_schedules();

  RETURN jsonb_build_object(
    'reconcile_before', v_reconcile_before,
    'generation', v_generation,
    'reconcile_after', v_reconcile_after
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_contract_financial_state(p_contract_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contract public.contracts%ROWTYPE;
  v_canonical_paid numeric := 0;
  v_paid numeric := 0;
  v_previous_bypass text := COALESCE(current_setting('app.financial_controls_bypass', true), '');
BEGIN
  IF p_contract_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT *
  INTO v_contract
  FROM public.contracts contract
  WHERE contract.id = p_contract_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  v_canonical_paid := public.canonical_contract_paid_amount(p_contract_id);
  v_paid := CASE
    WHEN COALESCE(v_contract.contract_amount, 0) > 0
      THEN LEAST(v_canonical_paid, v_contract.contract_amount)
    ELSE v_canonical_paid
  END;

  PERFORM set_config('app.financial_controls_bypass', 'on', true);

  UPDATE public.contracts contract
  SET
    total_paid = v_paid,
    balance_due = GREATEST(COALESCE(v_contract.contract_amount, 0) - v_paid, 0),
    payment_status = CASE
      WHEN v_paid <= 0.01 THEN 'unpaid'
      WHEN v_paid >= COALESCE(v_contract.contract_amount, 0) - 0.01 THEN 'paid'
      ELSE 'partial'
    END,
    updated_at = now()
  WHERE contract.id = p_contract_id;

  PERFORM set_config('app.financial_controls_bypass', v_previous_bypass, true);
  RETURN v_paid;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM set_config('app.financial_controls_bypass', v_previous_bypass, true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_invoice_financial_state(p_invoice_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_paid numeric := 0;
  v_previous_bypass text := COALESCE(current_setting('app.financial_controls_bypass', true), '');
BEGIN
  IF p_invoice_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice
  WHERE invoice.id = p_invoice_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  v_paid := public.canonical_invoice_paid_amount(p_invoice_id, NULL);
  PERFORM set_config('app.financial_controls_bypass', 'on', true);

  UPDATE public.invoices invoice
  SET
    paid_amount = v_paid,
    balance_due = GREATEST(COALESCE(v_invoice.total_amount, 0) - v_paid, 0),
    payment_status = CASE
      WHEN v_paid <= 0.01 THEN 'unpaid'
      WHEN v_paid >= COALESCE(v_invoice.total_amount, 0) - 0.01 THEN 'paid'
      ELSE 'partial'
    END,
    status = CASE
      WHEN lower(COALESCE(v_invoice.status, '')) IN ('cancelled', 'canceled', 'void', 'voided', 'deleted')
        THEN v_invoice.status
      WHEN v_paid >= COALESCE(v_invoice.total_amount, 0) - 0.01 THEN 'paid'
      WHEN v_invoice.due_date IS NOT NULL AND v_invoice.due_date < CURRENT_DATE THEN 'overdue'
      WHEN lower(COALESCE(v_invoice.status, '')) = 'draft' THEN 'draft'
      ELSE 'sent'
    END,
    updated_at = now()
  WHERE invoice.id = p_invoice_id;

  PERFORM set_config('app.financial_controls_bypass', v_previous_bypass, true);
  RETURN v_paid;
EXCEPTION
  WHEN OTHERS THEN
    PERFORM set_config('app.financial_controls_bypass', v_previous_bypass, true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_contract_financial_state_v1(p_contract_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_jwt_role text := COALESCE(
    current_setting('request.jwt.claim.role', true),
    auth.jwt() ->> 'role',
    ''
  );
  v_contract_before public.contracts%ROWTYPE;
  v_contract_after public.contracts%ROWTYPE;
  v_invoice_id uuid;
  v_schedule_report jsonb;
BEGIN
  IF p_contract_id IS NULL THEN
    RAISE EXCEPTION 'contract id is required' USING ERRCODE = '22023';
  END IF;

  IF v_actor IS NULL AND v_jwt_role <> 'service_role' THEN
    RAISE EXCEPTION 'authenticated user is required' USING ERRCODE = '42501';
  END IF;

  SELECT contract.*
  INTO v_contract_before
  FROM public.contracts AS contract
  WHERE contract.id = p_contract_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'contract not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.profiles AS profile
    WHERE profile.user_id = v_actor
      AND profile.company_id = v_contract_before.company_id
      AND COALESCE(profile.is_active, true)
  ) THEN
    RAISE EXCEPTION 'contract is outside the current company scope'
      USING ERRCODE = '42501';
  END IF;

  FOR v_invoice_id IN
    SELECT invoice.id
    FROM public.invoices AS invoice
    WHERE invoice.contract_id = p_contract_id
      AND invoice.company_id = v_contract_before.company_id
      AND lower(COALESCE(invoice.status, '')) NOT IN (
        'cancelled', 'canceled', 'void', 'voided', 'deleted'
      )
    ORDER BY invoice.id
  LOOP
    PERFORM public.recalculate_invoice_financial_state(v_invoice_id);
  END LOOP;

  PERFORM public.recalculate_contract_financial_state(p_contract_id);

  v_schedule_report := public.reconcile_contract_schedules_v1(
    p_contract_id,
    jsonb_build_object('link_repair', true, 'settlement_sync', true)
  );

  SELECT contract.*
  INTO STRICT v_contract_after
  FROM public.contracts AS contract
  WHERE contract.id = p_contract_id;

  RETURN jsonb_build_object(
    'contract_id', p_contract_id,
    'contract_number', v_contract_after.contract_number,
    'changed',
      round(COALESCE(v_contract_before.total_paid, 0)::numeric, 2)
        IS DISTINCT FROM round(COALESCE(v_contract_after.total_paid, 0)::numeric, 2)
      OR round(COALESCE(v_contract_before.balance_due, 0)::numeric, 2)
        IS DISTINCT FROM round(COALESCE(v_contract_after.balance_due, 0)::numeric, 2)
      OR COALESCE(v_contract_before.payment_status, '')
        IS DISTINCT FROM COALESCE(v_contract_after.payment_status, '')
      OR COALESCE((v_schedule_report ->> 'changed')::boolean, false),
    'schedules', v_schedule_report,
    'before', jsonb_build_object(
      'total_paid', COALESCE(v_contract_before.total_paid, 0),
      'balance_due', COALESCE(v_contract_before.balance_due, 0),
      'payment_status', v_contract_before.payment_status
    ),
    'after', jsonb_build_object(
      'total_paid', COALESCE(v_contract_after.total_paid, 0),
      'balance_due', COALESCE(v_contract_after.balance_due, 0),
      'payment_status', v_contract_after.payment_status
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_invoice_on_payment_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id uuid;
  v_invoice_id uuid;
  v_contract_id uuid;
  v_invoice_ids uuid[] := ARRAY[]::uuid[];
  v_contract_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_payment_id := NEW.id;
    IF NEW.invoice_id IS NOT NULL THEN v_invoice_ids := array_append(v_invoice_ids, NEW.invoice_id); END IF;
    IF NEW.contract_id IS NOT NULL THEN v_contract_ids := array_append(v_contract_ids, NEW.contract_id); END IF;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_payment_id := OLD.id;
    IF OLD.invoice_id IS NOT NULL THEN v_invoice_ids := array_append(v_invoice_ids, OLD.invoice_id); END IF;
    IF OLD.contract_id IS NOT NULL THEN v_contract_ids := array_append(v_contract_ids, OLD.contract_id); END IF;
  END IF;

  SELECT
    v_invoice_ids || COALESCE(array_agg(DISTINCT allocation.target_id), ARRAY[]::uuid[])
  INTO v_invoice_ids
  FROM public.payment_allocations allocation
  WHERE allocation.payment_id = v_payment_id
    AND allocation.allocation_type = 'invoice';

  FOR v_invoice_id IN
    SELECT DISTINCT candidate_id
    FROM unnest(v_invoice_ids) candidate(candidate_id)
    WHERE candidate_id IS NOT NULL
  LOOP
    PERFORM public.recalculate_invoice_financial_state(v_invoice_id);
    SELECT invoice.contract_id INTO v_contract_id
    FROM public.invoices invoice WHERE invoice.id = v_invoice_id;
    IF v_contract_id IS NOT NULL THEN
      v_contract_ids := array_append(v_contract_ids, v_contract_id);
    END IF;
  END LOOP;

  FOR v_contract_id IN
    SELECT DISTINCT candidate_id
    FROM unnest(v_contract_ids) candidate(candidate_id)
    WHERE candidate_id IS NOT NULL
  LOOP
    PERFORM public.recalculate_contract_financial_state(v_contract_id);
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$
